void i_am_groot(int arr[], int n, int i){
    int j, d;
    if(i==n)
        return;

    if(*(arr+i)<*(arr+i-1)){
        for(j=0; j<n; j++){
            if(*(arr+i)<*(arr+j)){
                d=*(arr+i);
                *(arr+i)=*(arr+j);
                *(arr+j)=d;
            }    
        }   
    }

    else
        i_am_groot(arr, n, i+1);
}

